            };

        /// <summary>Looks an icon up by its antd name, for example "search".</summary>
        public static Geometry ByName(string name)
        {
            Geometry geometry;
            return name != null && Lookup.TryGetValue(name, out geometry) ? geometry : null;
        }

        public static IEnumerable<string> Names
        {
            get { return Lookup.Keys; }
        }

        private static Geometry Create(string data)
        {
            // Geometry.Parse returns an already frozen StreamGeometry, so the viewBox
            // offset has to live on a wrapping group instead of the geometry itself.
            var group = new GeometryGroup();
            group.Transform = new TranslateTransform(-64, -64);
            group.Children.Add(Geometry.Parse(data));
            group.Freeze();
            return group;
        }
    }
